import{_ as s,o as t,a as l,b as n}from"./app.C41L12d5.js";const i="/ascendc.github.io/assets/nz2nd_conversion_half.DAap6DUH.png",p="/ascendc.github.io/assets/nz2nd_conversion_float.Kj9w04Sz.png",N=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"数据搬运","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/data_move"},{"text":"DataCopy（UB -> GM随路转换NZ2ND搬运）","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_UBToGM_NZ2ND"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_UBToGM_NZ2ND.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_UBToGM_NZ2ND.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),e={name:"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_UBToGM_NZ2ND.md"};function d(c,a,r,o,h,_){return t(),l("div",null,[...a[0]||(a[0]=[n('<div><article class="markdown-body"><h1>DataCopy（UBToGM随路转换NZ2ND搬运）<span id="ZH-CN_TOPIC_0000002391805265"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section12840195813362"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>该接口为软仿接口，从易用性角度出发进行设计，支持在从Unified Buffer（UB）到Global Memory的数据搬运过程中进行NZ到ND格式的转换。</p><p>具体支持的数据通路为（以<a href="../../aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>UB -&gt; Global Memory <ul><li>VECOUT -&gt; GM</li></ul><div data-filter="310p"><ul><li>CO2 -&gt; GM（仅Atlas 推理系列产品AI Core支持）</li></ul></div></li></ul><h2 id="函数原型">函数原型<span id="section1792117555586"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>\n<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Nz2NdParamsFull</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>\n</code></pre></div><h2 id="参数说明">参数说明<span id="section14983445508"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">T</td><td align="left">源操作数或者目的操作数的数据类型。支持的数据类型请参考<a href="#section4219135304818">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 接口参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">dst</td><td align="center">输出</td><td align="left">目的操作数，类型为<a href="../../data_structures/GlobalTensor/GlobalTensor_intro.html">GlobalTensor</a>。</td></tr><tr><td align="left">src</td><td align="center">输入</td><td align="left">源操作数，类型为<a href="../../data_structures/LocalTensor/LocalTensor_intro.html">LocalTensor</a>。</td></tr><tr><td align="left">intriParams</td><td align="center">输入</td><td align="left">搬运参数，类型为Nz2NdParamsFull，具体参数请参考<a href="#table_nz2nd_3">表3</a>。<br>具体定义请参考<code>${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>，<code>${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表3</strong> Nz2NdParamsFull结构体内参数定义<span id="table_nz2nd_3"></span></p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">ndNum</td><td align="left">传输NZ矩阵的数目，取值范围：ndNum∈[0, 4095]。</td></tr><tr><td align="left">nValue</td><td align="left">NZ矩阵的行数，取值范围：nValue∈[1, 8192]。</td></tr><tr><td align="left">dValue</td><td align="left">NZ矩阵的列数，取值范围：dValue∈[1, 8192]。dValue必须为16的倍数。</td></tr><tr><td align="left">srcNdMatrixStride</td><td align="left">源相邻NZ矩阵的偏移（头与头），取值范围：srcNdMatrixStride∈[1, 512]，单位256（16 * 16）个元素。</td></tr><tr><td align="left">srcNStride</td><td align="left">源同一NZ矩阵的相邻Z排布的偏移（头与头），取值范围：srcNStride∈[0, 4096]，单位16个元素。</td></tr><tr><td align="left">dstDStride</td><td align="left">目的ND矩阵的相邻行的偏移（头与头），取值范围：dstDStride∈[1, 65535]，单位为元素。</td></tr><tr><td align="left">dstNdMatrixStride</td><td align="left">目的ND矩阵中，来自源相邻NZ矩阵的偏移（头与头），取值范围：dstNdMatrixStride∈[1, 65535]，单位为元素。</td></tr></tbody></table><p>以half数据类型为例，NZ2ND转换示意图如下，样例中参数设置值和解释说明如下：</p><ul><li>ndNum = 2，表示源NZ矩阵的数目为2（NZ矩阵1为A1~A4 + B1~B4，NZ矩阵2为C1~C4 + D1~D4）。</li><li>nValue = 4，NZ矩阵的行数，也就是矩阵的高度为4。</li><li>dValue = 32，NZ矩阵的列数，也就是矩阵的宽度为32个元素。</li><li>srcNdMatrixStride = 1，表达相邻NZ矩阵起始地址间的偏移，即为A1~C1的距离，即为256个元素（16个DataBlock * 16个元素）。</li><li>srcNStride = 4，表示同一个源NZ矩阵的相邻Z排布的偏移，即为A1到B1的距离，即为64个元素（4个DataBlock * 16个元素）。</li><li>dstDStride = 160，表达一个目的ND矩阵的相邻行之间的偏移，即A1和A2之间的距离，即为10个DataBlock，即10 * 16 = 160个元素。</li><li>dstNdMatrixStride = 48，表达dst中第x个目的ND矩阵的起点和第x+1个目的ND矩阵的起点的偏移，即A1和C1之间的距离，即为3个DataBlock，3 * 16 = 48个元素。</li></ul><p><strong>图1</strong> NZ2ND转换示意图（half数据类型）<span id="fig15851251122815"></span><br><img src="'+i+'" alt title="NZ2ND转换示意图（half数据类型）"></p><p>以float数据类型为例，NZ2ND转换示意图如下，样例中参数设置值和解释说明如下：</p><ul><li>ndNum = 2，表示源NZ矩阵的数目为2（NZ矩阵1为A1~A8 + B1~B8，NZ矩阵2为C1~C8 + D1~D8）。</li><li>nValue = 4，NZ矩阵的行数，也就是矩阵的高度为4。</li><li>dValue = 32，NZ矩阵的列数，也就是矩阵的宽度为32个元素。</li><li>srcNdMatrixStride = 1，表达相邻NZ矩阵起始地址间的偏移，即A1到C1的距离，为256个元素（32个DataBlock * 8个元素）。</li><li>srcNStride = 4，表示同一个源NZ矩阵的相邻Z排布的偏移，即A1到B1的距离，为64个元素（8个DataBlock * 8个元素）。</li><li>dstDStride = 144，表示一个目的ND矩阵的相邻行之间的偏移，即A1和A3之间的距离，为18个DataBlock，即18 * 8 = 144个元素。</li><li>dstNdMatrixStride = 40，表示dst中第x个目的ND矩阵的起点和第x+1个目的ND矩阵的起点的偏移，即A1和C1之间的距离，为5个DataBlock，5 * 8 = 40个元素。</li></ul><p><strong>图2</strong> NZ2ND转换示意图（float数据类型）<span id="fig5586175192811"></span><br><img src="'+p+`" alt title="NZ2ND转换示意图（float数据类型）"></p><h2 id="数据类型">数据类型<span id="section4219135304818"></span><a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，支持的数据类型为：bool、int8_t、uint8_t、hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core，支持的数据类型为：int16_t、uint16_t、half、int32_t、uint32_t、float。</li></ul></div><h2 id="返回值说明">返回值说明<span id="section129001927113216"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section830051273220"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>该接口为软仿接口，从易用性角度出发进行设计。</p></li><li><p>Nz2NdParamsFull结构体参数的值需在取值范围内：</p><p><strong>表4</strong> Nz2NdParamsFull结构体参数取值范围</p><table><thead><tr><th>参数名</th><th>取值范围</th></tr></thead><tbody><tr><td>ndNum</td><td>[0, 4095]</td></tr><tr><td>nValue</td><td>[1, 8192]</td></tr><tr><td>dValue</td><td>[1, 8192]</td></tr><tr><td>srcNdMatrixStride</td><td>[1, 512]</td></tr><tr><td>srcNStride</td><td>[0, 4096]</td></tr><tr><td>dstDStride</td><td>[1, 65535]</td></tr><tr><td>dstNdMatrixStride</td><td>[1, 65535]</td></tr></tbody></table></li></ul><h2 id="调用示例">调用示例<span id="section2409153316111"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>intriParams参数解析请参考<a href="#fig15851251122815">图1</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// srcLocal为half类型的LocalTensor，dstGlobal为half类型的GlobalTensor。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Nz2NdParamsFull</span><span class="w"> </span><span class="n">intriParams</span><span class="p">{</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">};</span>
<span class="c1">// Local Memory -&gt; Global Memory</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">intriParams</span><span class="p">);</span>
</code></pre></div><p>结果示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>输入数据(srcLocal): [1 2 3 ... 1024]
输出数据(dstGlobal):[1 2 ... 15 16 513 514 ... 527 528 17 18 ... 31 32 529 530 ... 543 544 ...497 498 ...  511 512  1009 1010... 1023 1024]
</code></pre></div></article></div>`,1)])])}const f=s(e,[["render",d]]);export{N as __pageData,f as default};
